const oldFile = {
  contents: "export function greet(name: string) {\n  return `Hello, ${name}`;\n}\n",
  name: "greeting.ts",
};

const newFile = {
  contents:
    'export function greet(name: string = "world") {\n  const greeting = `Welcome, ${name}!`;\n  return greeting;\n}\n',
  name: "greeting.ts",
};

export { oldFile, newFile };

import { useState } from "react";
import {
  DiffView,
  DiffViewHeader,
  DiffViewTitle,
  DiffViewStats,
  DiffViewActions,
  DiffViewCopyButton,
  DiffViewContent,
} from "@/registry/erbium/blocks/diff-view";
import { CopyButtonIcon, CopyButtonLabel } from "@/registry/erbium/blocks/copy-button";
import { Toggle } from "@/registry/erbium/ui/toggle";
import { oldFile, newFile } from "../examples/files";

const Example = () => {
  const [unified, setUnified] = useState(false);

  return (
    <DiffView
      className="w-full max-w-4xl"
      oldFile={oldFile}
      newFile={newFile}
      options={{ diffStyle: unified ? "unified" : "split" }}
    >
      <DiffViewHeader>
        <div className="flex min-w-0 items-center gap-3">
          <DiffViewTitle />
          <DiffViewStats />
        </div>
        <DiffViewActions>
          <Toggle pressed={unified} onPressedChange={setUnified} size="sm">
            Unified
          </Toggle>
          <DiffViewCopyButton side="old">
            <CopyButtonIcon />
            <CopyButtonLabel>Copy before</CopyButtonLabel>
          </DiffViewCopyButton>
          <DiffViewCopyButton>
            <CopyButtonIcon />
            <CopyButtonLabel>Copy after</CopyButtonLabel>
          </DiffViewCopyButton>
        </DiffViewActions>
      </DiffViewHeader>
      <DiffViewContent className="max-h-80" />
    </DiffView>
  );
};

export default Example;
